WFJ.Data.add("quest", {
  [9000] = { "最高のものは最後に", "Beaststalker's CapとBeaststalker's TunicをDelianaに渡して下さい。", "すごい話ね、{name}！あなたには感謝するわ。関わった人たちみんなも、心から感謝しているはずよ。これでやっと、夜は両目を閉じて眠れるかもしれないわ。\n\n報酬のことだけど、あなたがきっと気に入る品がいくつかあると思うの。", "取り決め通り、新しいBeastmaster's CapとTunicと引き換えに、お前のBeaststalkerの装備を渡す用意はできているか？", "寂しくなるわ、{name}。あなたにはとても大きな恩があるの。一生かかっても返せそうにないわ。\n\n新しい頭と胴の防具を気に入ってくれるといいわ。そして、この先ずっとあなたを守ってくれますように。", 0x48402900, 0x2be5774f, 0x03db6ed6, 0x043c7993, 0x2cf1dd7a, "....." },
  [9001] = { "最高のものは最後に", "Magister's CrownとMagister's RobesをDelianaに渡して下さい。", "すごい話ね、{name}！あなたには感謝するわ。関わった人たちみんなも、心から感謝しているはずよ。これでやっと、夜は両目を閉じて眠れるかもしれないわ。\n\n報酬のことだけど、あなたがきっと気に入る品がいくつかあると思うの。", "取り決め通り、新しいSorcerer's CrownとRobesと引き換えに、お前のMagisterの装備を渡す用意はできているか？", "寂しくなるわ、{name}。あなたにはとても大きな恩があるの。一生かかっても返せそうにないわ。\n\n新しい頭と胴の防具を気に入ってくれるといいわ。そして、この先ずっとあなたを守ってくれますように。", 0x48402900, 0x62abd2ed, 0x03db6ed6, 0xe56a41b3, 0x2cf1dd7a, "....." },
