  [9006] = { "最高のものは最後に", "Helm of ValorとBreastplate of ValorをDelianaに渡して下さい。", "すごい話ね、{name}！あなたには感謝するわ。関わった人たちみんなも、心から感謝しているはずよ。これでやっと、夜は両目を閉じて眠れるかもしれないわ。\n\n報酬のことだけど、あなたがきっと気に入る品がいくつかあると思うの。", "取り決め通り、新しいHelm and Breastplate of Heroismと引き換えに、お前のValorの装備を渡す用意はできているか？", "寂しくなるわ、{name}。あなたにはとても大きな恩があるの。一生かかっても返せそうにないわ。\n\n新しい頭と胴の防具を気に入ってくれるといいわ。そして、この先ずっとあなたを守ってくれますように。", 0x48402900, 0x1cadf847, 0x03db6ed6, 0x15d8c720, 0x2cf1dd7a, "....." },
  [9007] = { "最後のために一番良い物を取っておく", "Wildheart CowlとWildheart VestをMokvarに渡して下さい。", "本当に面白い物語だったよ、{name}! 君には感謝と、巻き込まれた人たちすべてに心からの謝意を捧げるよ。保証する。君の努力を通じて、我々は過去の過ちから解放されたんだ。\n\nお礼に、君の努力のたまものとしてすごく喜んでもらえる物をいくつか持ってるんだ。", "取り決め通り、新しいFeralheart CowlとVestと引き換えに、お前のWildheartの装備を渡す用意はできているか？", "{name}、君がいなくなると本当に寂しくなるよ。君には借りがあるけれど、俺はその借りを返すことができないかもしれない。\n\n新しい鎧と兜で楽しんでくれよな。これが長い間君を守ってくれますように。そして、大いなる名誉を達成するのを助けますように!", 0x48402900, 0xa5f70ad7, 0xf3ed443f, 0x7a344d64, 0xe7bcdb0b, "....." },
