  [9011] = { "最後のために一番良い物を取っておく", "Coif of ElementsとVest of ElementsをMokvarに渡して下さい。", "本当に面白い物語だったよ、{name}! 君には感謝と、巻き込まれた人たちすべてに心からの謝意を捧げるよ。保証する。君の努力を通じて、我々は過去の過ちから解放されたんだ。\n\nお礼に、君の努力のたまものとしてすごく喜んでもらえる物をいくつか持ってるんだ。", "取り決め通り、新しいCoif and Vest of The Five Thundersと引き換えに、お前のElementsの装備を渡す用意はできているか", "{name}、君がいなくなると本当に寂しくなるよ。君には借りがあるけれど、俺はその借りを返すことができないかもしれない。\n\n新しい鎧と兜で楽しんでくれよな。これが長い間君を守ってくれますように。そして、大いなる名誉を達成するのを助けますように!", 0x48402900, 0xec6bc449, 0xf3ed443f, 0x4e769c4f, 0xe7bcdb0b, "....." },
  [9012] = { "最後のために一番良い物を取っておく", "Dreadmist MaskとDreadmist RobeをMokvarに渡して下さい。", "本当に面白い物語だったよ、{name}! 君には感謝と、巻き込まれた人たちすべてに心からの謝意を捧げるよ。保証する。君の努力を通じて、我々は過去の過ちから解放されたんだ。\n\nお礼に、君の努力のたまものとしてすごく喜んでもらえる物をいくつか持ってるんだ。", "取り決め通り、新しいDeathmist MaskとRobeと引き換えに、お前のDreadmistの装備を渡す用意はできているか？", "{name}、君がいなくなると本当に寂しくなるよ。君には借りがあるけれど、俺はその借りを返すことができないかもしれない。\n\n新しい鎧と兜で楽しんでくれよな。これが長い間君を守ってくれますように。そして、大いなる名誉を達成するのを助けますように!", 0x48402900, 0x127e82e7, 0xf3ed443f, 0x655b2731, 0xe7bcdb0b, "....." },
  [9013] = { "最後のために一番良い物を取っておく", "Helm of ValorとBreastplate of ValorをMokvarに渡して下さい。", "本当に面白い物語だったよ、{name}! 君には感謝と、巻き込まれた人たちすべてに心からの謝意を捧げるよ。保証する。君の努力を通じて、我々は過去の過ちから解放されたんだ。\n\nお礼に、君の努力のたまものとしてすごく喜んでもらえる物をいくつか持ってるんだ。", "取り決め通り、新しいHelm and Breastplate of Heroismと引き換えに、お前のValorの装備を渡す用意はできているか？", "{name}、君がいなくなると本当に寂しくなるよ。君には借りがあるけれど、俺はその借りを返すことができないかもしれない。\n\n新しい鎧と兜で楽しんでくれよな。これが長い間君を守ってくれますように。そして、大いなる名誉を達成するのを助けますように!", 0x48402900, 0x88cbb0c8, 0xf3ed443f, 0x15d8c720, 0xe7bcdb0b, "....." },
  [9014] = { "最後のために一番良い物を取っておく", "Magister's CrownとMagister's RobesをMokvarに渡して下さい。", "本当に面白い物語だったよ、{name}! 君には感謝と、巻き込まれた人たちすべてに心からの謝意を捧げるよ。保証する。君の努力を通じて、我々は過去の過ちから解放されたんだ。\n\nお礼に、君の努力のたまものとしてすごく喜んでもらえる物をいくつか持ってるんだ。", "取り決め通り、新しいSorcerer's CrownとRobesと引き換えに、お前のMagisterの装備を渡す用意はできているか？", "{name}、君がいなくなると本当に寂しくなるよ。君には借りがあるけれど、俺はその借りを返すことができないかもしれない。\n\n新しい鎧と兜で楽しんでくれよな。これが長い間君を守ってくれますように。そして、大いなる名誉を達成するのを助けますように!", 0x48402900, 0x7709da32, 0xf3ed443f, 0xe56a41b3, 0xe7bcdb0b, "....." },
  [9015] = { "挑戦", "Blackrock DepthsのRing of the Lawへ行き、High Justice Grimstoneから判決を下されるよう、中心にBanner of Provocationを立てて下さい。Theldrenと剣闘士たちを討ち取り、Eastern PlaguelandsのAnthion Harmonの元へ、Lord Valthalakの護符の一番上の破片を持ち帰って下さい。", "よく聞くのだ、{name}。旗を望みどおりに働かせるには、Blackrock DepthsのRing of the Lawへ足を踏み入れねばならない。High Justice Grimstoneに判決を下させ、反抗の印として旗を地面にしっかりと立てるのだ。\n\n狙った相手は自分を抑えられず、お前と戦いたいという欲望に満ちて戦いに加わるだろう。求めるものを手に入れたら、Anthionのところへ戻るのだ。", "戻ったか、{name}！", "メダルの破片を取り戻してきたのかい、{name}?", 0xc6735ff8, 0xb45640a2, 0x506b86a7, 0xa0760cc3, 0x144fdc51, "....." },
  [9016] = { "Anthionの遺言", "OrgimmarのMokvarにWildheart Boots・Wildheart Kilt・Wildheart Spauldersを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Mokvarのところへ戻り、彼に伝えてくれ。残りの破片を見つける唯一の望みはBodleyだと。手筈を整えた君への報酬については、彼と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか。その目を見れば、話したいことが山ほどあるのが分かるぞ、{name}。まずは報酬を片付けよう。", "ただのメダルのために、この呪いが我々に与えられたんだ。Lord Valthalakは確かに、怨みの保ち方を知っていたんだな。\n\n残りの破片を見つける努力をせねばなるまい……願わくば、早死にする前にね。でもその前に、君への報酬を検討させてくれ。", 0x4e493fc8, 0x03ea45cc, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9017] = { "Anthionの遺言", "OrgimmarのMokvarにBeaststalker's Boots・Beaststalker's Pants・Beaststalker's Mantleを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Mokvarのところへ戻り、彼に伝えてくれ。残りの破片を見つける唯一の望みはBodleyだと。手筈を整えた君への報酬については、彼と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか。その目を見れば、話したいことが山ほどあるのが分かるぞ、{name}。まずは報酬を片付けよう。", "ただのメダルのために、この呪いが我々に与えられたんだ。Lord Valthalakは確かに、怨みの保ち方を知っていたんだな。\n\n残りの破片を見つける努力をせねばなるまい……願わくば、早死にする前にね。でもその前に、君への報酬を検討させてくれ。", 0x4e493fc8, 0xa6305b9b, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9018] = { "Anthionの遺言", "OrgimmarのMokvarにMagister's Boots・Magister's Leggings・Magister's Mantleを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Mokvarのところへ戻り、彼に伝えてくれ。残りの破片を見つける唯一の望みはBodleyだと。手筈を整えた君への報酬については、彼と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか。その目を見れば、話したいことが山ほどあるのが分かるぞ、{name}。まずは報酬を片付けよう。", "ただのメダルのために、この呪いが我々に与えられたんだ。Lord Valthalakは確かに、怨みの保ち方を知っていたんだな。\n\n残りの破片を見つける努力をせねばなるまい……願わくば、早死にする前にね。でもその前に、君への報酬を検討させてくれ。", 0x4e493fc8, 0x36c3529b, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9019] = { "Anthionの遺言", "OrgimmarのMokvarにDevout Sandals・Devout Skirt・Devout Mantleを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Mokvarのところへ戻り、彼に伝えてくれ。残りの破片を見つける唯一の望みはBodleyだと。手筈を整えた君への報酬については、彼と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか。その目を見れば、話したいことが山ほどあるのが分かるぞ、{name}。まずは報酬を片付けよう。", "ただのメダルのために、この呪いが我々に与えられたんだ。Lord Valthalakは確かに、怨みの保ち方を知っていたんだな。\n\n残りの破片を見つける努力をせねばなるまい……願わくば、早死にする前にね。でもその前に、君への報酬を検討させてくれ。", 0x4e493fc8, 0xceb83d1b, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9020] = { "Anthionの遺言", "OrgimmarのMokvarにShadowcraft Boots・Shadowcraft Pants・Shadowcraft Spauldersを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Mokvarのところへ戻り、彼に伝えてくれ。残りの破片を見つける唯一の望みはBodleyだと。手筈を整えた君への報酬については、彼と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか。その目を見れば、話したいことが山ほどあるのが分かるぞ、{name}。まずは報酬を片付けよう。", "ただのメダルのために、この呪いが我々に与えられたんだ。Lord Valthalakは確かに、怨みの保ち方を知っていたんだな。\n\n残りの破片を見つける努力をせねばなるまい……願わくば、早死にする前にね。でもその前に、君への報酬を検討させてくれ。", 0x4e493fc8, 0xcecbaf6e, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9021] = { "Anthionの遺言", "OrgimmarのMokvarにDreadmist Sandals・Dreadmist Leggings・Dreadmist Mantleを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Mokvarのところへ戻り、彼に伝えてくれ。残りの破片を見つける唯一の望みはBodleyだと。手筈を整えた君への報酬については、彼と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか。その目を見れば、話したいことが山ほどあるのが分かるぞ、{name}。まずは報酬を片付けよう。", "ただのメダルのために、この呪いが我々に与えられたんだ。Lord Valthalakは確かに、怨みの保ち方を知っていたんだな。\n\n残りの破片を見つける努力をせねばなるまい……願わくば、早死にする前にね。でもその前に、君への報酬を検討させてくれ。", 0x4e493fc8, 0xd3297fbe, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9022] = { "Anthionの遺言", "OrgimmarのMokvarにBoots of Valor・Legplates of Valor・Spaulders of Valorを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Mokvarのところへ戻り、彼に伝えてくれ。残りの破片を見つける唯一の望みはBodleyだと。手筈を整えた君への報酬については、彼と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか。その目を見れば、話したいことが山ほどあるのが分かるぞ、{name}。まずは報酬を片付けよう。", "ただのメダルのために、この呪いが我々に与えられたんだ。Lord Valthalakは確かに、怨みの保ち方を知っていたんだな。\n\n残りの破片を見つける努力をせねばなるまい……願わくば、早死にする前にね。でもその前に、君への報酬を検討させてくれ。", 0x4e493fc8, 0xf397e78b, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9023] = { "比類なき毒", "Cenarion HoldのDirk Thunderwoodは、Venoxis's Venom SacとKurinnaxx's Venom Sacを持ってくるよう求めています。", "私と兄弟は、Ravenholdtの館で毒の仕事を取り仕切っている。\n\nLord Ravenholdtは私に、Zul'GurubとRuins of Ahn'Qirajに棲む者たちの毒袋から作れる、新しくて極めて効果の高い毒の配合を探し出すよう命じた。\n\nあの忌まわしい遺跡には、我々が求めているものを持っているかもしれない、特に毒の強い獣が2体棲んでいる、{class}。KurinnaxxとVenoxisという獣から毒袋を持ってきてくれれば、永遠に感謝するだろう。", "これは殴って奪って終わりという仕事じゃないぞ、{name}。友を連れて行く必要がある。", "Ravenholdtは君に感謝している、英雄よ! 好きな物を持って行ってくれ!", 0xa122e31b, 0xccf6f935, 0x7be5d33f, 0xda1def79, 0xf94a859c, "....." },
  [9024] = { "Aristanの直感", "StormwindのTrade DistrictにいるMorgan Pestleに、Cologne BottleとPerfume Bottleを1本ずつ渡して下さい。", "分かったぞ! 風に乗ってくる新しい香りを嗅いだかね? 流行り出した新しいコロンや香水だ。我々の衛兵が、あれほどたやすく任務を怠るはずがない。\n\nもっとも、彼らの思考が何か汚らわしい錬金術で曇らされているのなら話は別だ。\n\n確かめる方法は一つしかない。コロンと香水を一瓶ずつMorgan Pestleのところへ持って行き、私の疑いを伝えてくれ。戻ってきたら、購入代金は払い戻そう。", "何かお手伝いできることはあるかな?", "Aristanの心配も分かるが、いささか大げさに考えすぎだと思うよ。若い男も女も、したいようにさせておけばいい。Aristanは、若くて恋をしているということがどういうものか、忘れてしまったんだろうな。\n\nだが、そう本人に言わない方がいいだろう。ここは付き合ってやることにしよう。", 0xbf4e5c34, 0x40cb68d0, 0x707e9534, 0xdf112bb5, 0x261a5993, "....." },
  [9025] = { "Morganの発見", "Aristan Mottarのところへ戻って下さい。彼はStormwindのTrade District内にある銀行の外にいます。", "おやまあ。結局のところ、Aristanは何かをつかんでいたのかもしれないな。惚れ薬や、たちの悪い精神を変える薬に使われる物質の痕跡が見つかったよ。\n\n香水にそういうものが少し含まれていること自体は珍しくない。だが、私が検出した材料のいくつかは……妙な匂いがするんだ。", nil, "こうなっているだろうとは思っていたが、自分の疑いが正しかったと分かるのは、やはり落ち着かないものだ。次の手は慎重に考えねばならない。\n\nこれを受け取ってくれ。コロンと香水の代金だ。", 0x00276958, 0x74854d2a, 0x275c2471, nil, 0xa0c5854e, "...m." },
  [9026] = { "発生源の追跡", "StormwindのTrade District内にある「The Gilded Rose」のInnkeeper Allisonと話して下さい。", "発生源を見つけなくちゃならない。普段より多くの人たち……ガードも含めて、「The Gilded Rose」に出入りしているのを見たんだ。Allisonに話しかけてくれ。もし彼女がそれを売っているのなら、どこから仕入れてきたのか教えてくれるだろう。", nil, "ああ、そうだ、香水とコロンはついこの間仕入れたばかりでね。とてもよく売れていて、棚にどれだけ置いておけるか分からないよ。\n\n私に言わせれば、少々つまらないがね。みんなが同じ匂いだって? いい香りではあるけれど、それでもね。", 0xc4ef4d74, 0x9259fd91, 0xf8ad7b44, nil, 0x15074611, "...m." },
  [9027] = { "発生源の追跡", "Stormwindの水路沿いにある裁縫屋「The Finest Thread」のEvert Sorisamと話して下さい。", "コロンに何かおかしなところがあるって? ありうるね。一つの商品をこんなに多くの人が求めるのは見たことがないよ。\n\nいいかい、もし何か問題があるなら、私だって知りたい。仕入れはEvert Sorisamという商人からだよ。彼は町に来たばかりなんだ。\n\nThe Finest Threadに届ける品物があるって言ってたよ。", nil, "ああ、もちろんだとも。あの香りは今の季節で一番の売れ筋でね。この一時間であれを尋ねてきたのは、君で五人目か六人目じゃないかな。\n\nあいにく、うちの在庫は全部売り切れてしまってね。欲しいなら、The Gilded Roseの宿屋の主人、Allisonに話してみるといい。\n\nだが、ぐずぐずしない方がいいよ。あの香水には抗えないと分かるはずだ。", 0xc4ef4d74, 0xec408413, 0xd233b69d, nil, 0x0f5247b3, "...m.", nil, nil, nil, nil, 0xb83ac954 },
  [9028] = { "原因は暴かれた", "Apothecary Staffron Lerentを見つけて下さい。彼はHillsbrad FoothillsのRavenholdt Manorを過ぎたところにいます。", "何だって? 反逆? いやいや。誓って言うが、私の意図はまったく無害なものだよ。\n\n求愛という苦しい儀式を楽にしたいと願う者たちを手助けするのが、そんなに悪いことかね? さあ、それは罪ではないだろう。\n\n悪意がないことを証明するために、仕入れ先まで教えてあげよう。\n\nそれはStaffron Lerentという、何かの薬剤師らしい男から送られてきたものだ。彼と話したことは一度もない。\n\n仲介役のゴブリンの話では、彼はHillsbradの上の丘陵地帯、あの謎めいたRavenholdt Manorの先で仕事をしているそうだ。見つけられるといいね。", nil, "そうだ、あの香りを作ったのは私だ。素晴らしい香りだろう? 抗いがたい。\n\nAllianceとHordeのウォリアーたちが等しくこの恋の情に囚われれば、奴らにはShadow Councilの台頭を止める力など残っていない。\n\n奴らは弱り、備えを失う。愛する者を案じるうちに、その鋭さは鈍っていくのだ。\n\n答えはあまりにも単純だった。なぜ思い至るまでにこれほどかかったのか? すべての者の弱点は心を通じてある。そして避けられぬものを、お前に止める術はない。", 0xf2e77961, 0x9b987c7a, 0x9dec14e0, nil, 0x904005d0, "...m." },
  [9029] = { "泡立つ大釜", nil, nil, nil, "大釜から心地よい香りが漂ってくる。", 0xadb71af2, nil, nil, nil, 0x175eed11, ".mmm." },
  [9030] = { "Anthionの別れの言葉", "IronforgeのDelianaと話して下さい。", "Valthalakの魂はこのアミュレットに封じられていた。我々は欲に駆られ、待ち受ける呪いも知らずに、愚かにもそれを三つに分けてしまったのだ。\n\nValthalakの呪文を止める唯一の方法は、メダリオンを元通りに組み直すことだ。Delianaのもとへ戻り、残りの欠片を見つけるための唯一の望みはBodleyだと伝えてくれ。\n\n私はようやく安らかに眠れる。幸運を祈る。お前にはそれが必要になるだろうからな！", nil, nil, 0x4e493fc8, 0xa520f889, 0xfc39c874, nil, nil, "...mm" },
  [9032] = { "Bodleyの不幸な運命", "Blackrock Mountainへ行き、Extra-Dimensional Ghost Revealerを使ってBlackrock Spireの近くにいるBodleyを見つけて下さい。", "メダルにValthalakの魂が入ってるって? こんな強力な呪いで守られていたとしてもおかしくないね。\n\nBodleyの捜索は今のところちょっとした問題がある。最後に彼について聞いたのは、彼が危険を冒してBlackrock Spireへ戻る準備をしているということだったよ。再び彼について聞くことはなかった。\n\nBlackrock Mountainで彼を捜し出してほしいのだけれど、既に彼は死んでいるかもしれない。ゴブリンの装置を持って行くといい、友よ。", nil, "私のことが見えるとは嬉しいねえ。ついに人に話しかけられる!\n\n{name}、助けてくれるのか? 我々が犯した過ちを正し、物事を正しく直してくれると? すでにTop Piece of Lord Valthalaks Amuletを持っているというのが本当なら、他の二つの部分の正確な方角を示すことが出来ると思うよ。すべて繋ぎ合わせて、何もかも終わりにできる。\n\nおお、ところで。こんにちは、私の名はBodleyだ。君に会えてよかった!", 0x87a6a36a, 0x180c9e9b, 0x5728da71, nil, 0x077dc9c4, "...m." },
  [9033] = { "戦争の残響", "Eastern PlaguelandsのLight's Hope ChapelにいるCommander Eligor Dawnbringerは、Living Monstrositiesを$N1体、Stoneskin Gargoylesを$N2体、Deathknight Captainsを$N3体、Venom Stalkersを$N4体倒してほしいと言っています。", "前の戦争から五年……\n\n何万もの命が失われた。それが何のためだったというのか？脅威は完全に消え去ってはいなかったのだ。\n\nそしてLich Kingが再び蠢き出した……その腰巾着のKel'Thuzadが、我らの土地へのさらなる攻撃に向けて力を集めている。\n\n我々はそれを許さない！お前の献身を示せ。この狂気を止めるために命も手足も懸ける覚悟があると証明してみせろ。そうすれば、DawnとCrusadeの総力がお前の意のままとなるだろう。\n\nNaxxramasに入り、その中のScourgeを滅ぼせ……", "義務、名誉、献身……これらの言葉はお前にとって何を意味する？", "見事な働きだ！ Light's Hopeの男たち女たちの奉仕によって、君には報いがあるだろう。", 0xc78c127b, 0x5a6f59ac, 0x3ae1b39e, 0x7615fd9e, 0x06516fca, "....." },
  [9051] = { "毒の検証", "Devilsaur BarbをDevilsaurに突き刺して下さい。終わったら、Un'Goro CraterのTorwa Pathfinderのところへ戻って下さい。", "作るのを手伝ってもらったこの毒は、特別な事に使うんだ。巨大なdevilsaurのおかげで、クレーターで狩りをするのも生き残るのも難しくなってな。もしdevilsaurを殺すだけの力を持っていたとしても、devilsaurを殺せばまた別のdevilsaurがそいつの縄張りにやってくるだけで、切りがない。\n\n毒を塗ったこの矢じりを、生きたdevilsaurに深く突き刺してきてくれ。どれくらいで効くか分からんが、毒がそいつを静めてくれるはずだ……", "あの巨獣を鎮めることはできたか？", "ありがとう、{name}。君は勇敢で賢いな。\n\n教えてくれ、devilsaurの反応はどうだった?", 0x48054159, 0x6be611fa, 0x8ef8e482, 0x1e668d2c, 0x521708f1, "....." },
  [9052] = { "Bloodpetalの毒", "BloodcapとGorishi Stingをそれぞれ8つ集め、Un'Goro CraterのTorwa Pathfinderのところへ戻って下さい。", "ここに生息してる大きな生き物をなだめるのに使う、ちょっとした毒を作るのを助けてもらえないだろうか。死ぬようなのじゃないんだ、ただ{class}の鋭い目で素材を集めてもらいたくてね。\n\nbloodpetal sproutの中で成長するbloodcap mushroomはそこら中にあるし、Gorishi stingはクレーター南部に位置するSlithering Scarの周りにいる昆虫の中にある。", "うまくいったか？", "ついに材料が集まったか!\n\n集めておいたUn'Goro土と合わせれば、簡単に毒が調合できるぞ……", 0x1f178293, 0xf06ff794, 0xd296bd83, 0x7cadef78, 0x01ac2d01, "....." },
  [9053] = { "より良い素材", "Sunken Templeの最奥の守護者からPutrid Vineを入手し、Torwa Pathfinderのところへ戻って下さい。", "心配していたとおりだ……この毒はああいう強い生き物には弱すぎる、それだけだな。\n\n充分効果の高い毒を作るなら、Temple of Atal'Hakkarの奥へ行って祭壇の謎を解き、そこの守護者からputrid vineを見つけてこなくてはならん。神殿は危険だから、仲間を連れて行くべきだ。\n\n終わったら、私のところへ戻ってきてくれ。", "蔦は取り戻したか？", "ついに、毒が全部できるぞ。また恐竜に毒を使ってくれとは頼まないよ、もう君にはいろいろと頼んでしまったからな。\n\n感謝と尊敬の気持ちでいっぱいだ。君の旅がうまくいきますように、{name}。", 0xdb190fa9, 0x0ad68432, 0x3f4b427f, 0x25aa9248, 0xa8224e50, "....." },
  [9063] = { "Torwa Pathfinder", "Un'Goro CraterでTorwa Pathfinderと話して下さい。", "Torwa Pathfinderという名前の狩人がドルイドの助けを求めています。彼を助けるのに必要な腕前と自然への敬意を持っているのは、我々だけだそうです。\n\nUn'Goro CraterとTanaris砂漠をつなぐ道があります。そのクレーターへ入る道を行けば、すぐ近くにTorwaを見つけられるでしょう。", nil, "俺に会いに遠くからやって来たのか、{class}。それはちょうどよかった。", 0x168fa4b2, 0x21114ed8, 0x5987fa9c, nil, 0x75c76210, "...m." },
  [9065] = { "「Chow」クエスト (123)aa", "Kobold Verminを2体倒す。", "Kobold Verminを$N1体倒せ。", nil, nil, 0xdb0905c3, 0x314b469d, 0xb19a2ce2, nil, nil, "...mm" },
  [9085] = { "破滅の影", "召喚の輪へ行ってShadow of Doomを倒し、Eastern PlaguelandsのLight's Hope ChapelにいるCommander Thomas Helleranのところへ戻って下さい。", "攻撃を受けている地域に現れたScourgeの召喚の円の防御を崩せば、それを守る侍祭たちと対峙できるようになる。\n\n実のところ、あれは人間ではない。影であり、Lich Kingの配下の中でも最も恐ろしい存在の一つだ。奴らが持ち歩く死霊のルーンを使えば正体を暴くことができ、そのうえで魔法か武器の力で滅ぼせる。", "うまくいったか、{name}?", "見事な働きだ、{name}。影を滅ぼした今、Lich Kingがnecropolisを呼び戻し、我々を放っておく気になるのも時間の問題だろう。", 0xb93e11b0, 0xa5c9c54e, 0x3d7faa8c, 0x10763147, 0x6b4b125c, "....." },
  [9120] = { "Kel'Thuzadの最期", "Phylactery of Kel'ThuzadをEastern PlaguelandsのLight's Hope Chapelへ持って行って下さい。", "この経箱が、Naxxramasの主の残したすべてだ。良識に従えば、この経箱を破壊してリッチが二度と甦らないようにすべきだろう。ありがたいことに、あなたはその内なる理性の声にめったに耳を貸さない。\n\nLight's Hopeの誰かが、このアーティファクトに大金を払ってくれるはずだ。Kel'Thuzadが完全な力を取り戻したところで、誰が気にする？", nil, nil, 0x480d1191, 0x4c963af8, 0x2c6511e8, nil, nil, "...mm" },
  [9121] = { "恐怖の城塞 - Naxxramas", "Eastern PlaguelandsのLight's Hope ChapelにいるArchmage Angela Dosantosは、Arcane Crystalsを$N1個、Nexus Crystalsを$N2個、Righteous Orbを$N3個、そして$N4ゴールドを求めています。さらに、Argent DawnからHonoredの評価を得ている必要がある。", "Plaguewoodの奥深くに、恐るべき城塞Naxxramasの入口がある。これまで、中に入ろうとする試みはすべて、ルーンのポータルにかけられた魔法の結界に阻まれてきた。そう、今まではな。\n\n我々は秘術の隠蔽によって中へ入る方法を考え出した――Kirin Torの古い簡易呪文に、私が少し手を加えたものだ。{name}、Dawnの大義に対するお前の献身はいささか足りないので、代価は高くつくぞ。断って、「尊敬」か「崇拝」の評価になってから戻ってきて割引を受けるという選択もある。", "Naxxramasに足を踏み入れて、生きてその話を語り伝えた者はいない。", "少しピリピリする感覚があるだろう、{name}。その感覚は効いている証拠だ。終われば、Plaguewoodにあるルーンのポータルに乗ることで、Naxxramasに入れるようになる。", 0x289d201e, 0xbcee065c, 0xea550201, 0x9ab9bbde, 0xa4fd1bd1, "....." },
  [9122] = { "恐怖の城塞 - Naxxramas", "Eastern PlaguelandsのLight's Hope ChapelにいるArchmage Angela Dosantosは、Arcane Crystalsを$N1個、Nexus Crystalを$N2個、そして$N3ゴールドを求めています。さらに、Argent DawnからReveredの評価を得ている必要がある。", "Plaguewoodの奥深くに、恐るべき城塞Naxxramasの入口がある。これまで、中に入ろうとする試みはすべて、ルーンのポータルにかけられた魔法の結界に阻まれてきた。そう、今まではな。\n\n我々は、いわば永続的な秘術の隠蔽によって中へ入る方法を考え出した――Kirin Torの古い簡易呪文に、私が少し手を加えたものだ。とはいえ、この隠蔽には金がかかる。Dawnの大義に対するお前の献身は見事なものなので、その費用の一部は我々が負担しよう。", "Naxxramasに足を踏み入れて、生きてその話を語り伝えた者はいない。", "少しピリピリする感覚があるだろう、{name}。その感覚は効いている証拠だ。終われば、Plaguewoodにあるルーンのポータルに乗ることで、Naxxramasに入れるようになる。", 0x289d201e, 0xeb18bb5f, 0x3d6fd285, 0x9ab9bbde, 0xa4fd1bd1, "....." },
  [9123] = { "恐怖の城塞 - Naxxramas", "Eastern PlaguelandsのLight's Hope ChapelにいるArchmage Angela Dosantosが、Arcane Cloakingを無償で授けてくれる。Argent DawnからExaltedの評価を得ている必要がある。", "Plaguewoodの奥深くに、恐るべき城塞Naxxramasの入口がある。これまで、中に入ろうとする試みはすべて、ルーンのポータルにかけられた魔法の結界に阻まれてきた。そう、今まではな。\n\n我々は、いわば永続的な秘術の隠蔽によって中へ入る方法を考え出した――Kirin Torの古い簡易呪文に、私が少し手を加えたものだ。とはいえ、この隠蔽には金がかかる。だが、Dawnの大義に対するお前の献身は揺るぎない！費用はすべて免除しよう。", "Naxxramasに足を踏み入れて、生きてその話を語り伝えた者はいない。", "少しピリピリする感覚があるだろう、{name}。その感覚は効いている証拠だ。終われば、Plaguewoodにあるルーンのポータルに乗ることで、Naxxramasに入れるようになる。", 0x289d201e, 0x69b682cf, 0x92dc890b, 0x9ab9bbde, 0xa4fd1bd1, "....." },
  [9124] = { "Cryptstalkerの鎧は勝手にはできない……", "Eastern PlaguelandsのLight's Hope ChapelにいるHuntsman Leopoldは、Crypt Fiend Partsを$N1個求めています。", "このぴかぴかの記章を一枚、稼いでみる気はないか？\n\n<LeopoldがCrusadeの記章を掲げる。>\n\nちょっと困ったことがあってな、お前なら手を貸せるかもしれん、{name}。実はな、俺はNaxxramasに乗り込むような間抜けどものためにCryptstalkerの防具を作ってるんだ。防具の主な材料は奴らが持ってきてくれるんだが、crypt fiend partsだけはいつも切らしちまう。partsを一束持ってきてくれれば、記章で払ってやる――補給係のところで使えるぞ。", "狩りの首尾はどうだ？", "ああ、これは上出来だ、{name}。覚えておいてくれ、partsはいつでもさらに受け付けている。一束持ってくるたびに、報酬として記章をひとつ渡そう。", 0xa2b385ba, 0x5dad2579, 0x61c659aa, 0xe02b27bb, 0xe90182ae, "....." },
  [9126] = { "Bonescytheの発掘", "Eastern PlaguelandsのLight's Hope ChapelにいるRohan the Assassinは、Bone Fragmentsを$N1個求めています。", "Don JulioのBonescytheの防具の型紙にはbone fragmentsが要る――それも大量のbone fragmentsがな。Naxxramasに乗り込むような物好きどもが防具の主な材料は十分に持ってきてくれるが、Scourgeのbone fragmentsはいつだってもっと欲しいんだ。\n\nで、どうだ？手を汚しながら、ついでにScourgeを何体か片付けてみる気はないか？どっちにとっても得な話だぞ。", "skeletonがはびこる場所なら教えてやれるぞ、{class}。", "仕事が早いな、{name}。狐みたいに早い……そうだ、俺がバーバーショップ・カルテットにいた頃の話をしたことがあったか?\n\nいつかその話をするよう、思い出させてくれ。", 0x9cb81398, 0x4d2e7d99, 0x8dbeaf35, 0x3f157080, 0x2a565f14, "....." },
  [9128] = { "元素の方程式", "Eastern PlaguelandsのLight's Hope ChapelにいるArchmage Angela Dosantosは、Core of Elementsを$N1個求めています。", "ごきげんよう、冒険者！仕事に興味はあるかい？私は雇った者に記章で支払っている。この記章は補給係のところで力ある品を買うのに使えるんだ。\n\n頼みたいのは、運べるだけのcore of elementsを持ってきてもらうことだけさ。多ければ多いほどいい！\n\ncore of elementsは、この世界のあちこちにいる、形も大きさもさまざまなelementalsから手に入るよ。", "私にできるのは、正しい方角を指し示すことだけだ、{name}。", "見事な仕事だ、{name}!約束通り、この記章はお前のものだ。忘れるなよ、まだまだあるからな……", 0x32fba198, 0xd04e0226, 0x711686a0, 0xe334f68d, 0xa886b3a1, "....." },
  [9131] = { "Dreadnaughtの束縛", "Eastern PlaguelandsのLight's Hope ChapelにいるKorfaxは、Dark Iron Scrapsを$N1個求めています。", "Dreadnaughtの防具を見たことはあるか、{class}？いや、あるわけないな。お前はまだ子供だ――ちびすけだ。言っておくが、あれは見事なものだぞ。\n\nそれがお前に何の関係があるんだと思っているだろう？教えてやるよ、ひよっこ。俺にはDark Iron scrapsが必要で、手に入るだけ手に入れるためなら金を払うつもりだ。\n\nそのscrapsで、我らの勇者たちのためにDreadnaughtの一式を組み上げるんだ。scrapsを持ってくれば金を払う。", "<Korfaxがお前に唸り声をあげる。>\n\n何の用だ？道案内か？それなら教えてやれる……", "今のところはこれでいい。もっと手に入ったら、俺がどこにいるかは分かっているな。", 0xfcf29730, 0xdc148f79, 0xbec0de87, 0x56f85bce, 0x5422a5d8, ".....", nil, nil, 0x350c2585, nil, nil },
  [9136] = { "荒々しき植物", "Eastern PlaguelandsのLight's Hope ChapelにいるRayneは、Savage Frondsを$N1個求めています。", "私は、Naxxramasに入る勇敢な英雄たちのために、Dreamwalkerと呼ばれる特別な防具を作っています。材料のほとんどは彼らが用意してくれますが、この世界の植物からsavage frondsを採ってこられる人はいつでも探しているのです。\n\nこの仕事を自分にはふさわしくないと思うかもしれませんが、frondsがなければ防具は作れません。\n\nそれに、DawnとCrusadeの両方から資金を受けているので、私はお好みの記章で支払えるという珍しい立場にいるのですよ。", "私はこの世界の植物について深い知識を持っている。道案内が必要か？", "心から感謝します、{name}。\n\n<Rayneがお辞儀をする。>\n\nfrondsはいつでも受け付けていることを、覚えておいてください。", 0x8bdd8753, 0xff83eb0b, 0xf17f2db9, 0x23478164, 0xf8e6c80c, "....." },
  [9141] = { "人呼んで「The Rooster」", "Eastern PlaguelandsのLight's Hope ChapelにいるDispatch Commander Metzは、Argent Dawn Valor Tokenを求めています。", "令状が欲しいだと？何だって？顔を出しただけで、誰もが欲しがる作業指示書を渡してもらえるとでも思ってるのか？そうはいかんぞ、ひよっこ。世界中の職人が、ここ前線での仕事を求めて競り合っているんだ。\n\n作業指示書が欲しけりゃ、大義のために血を流す覚悟があるところを見せてもらおう。valor tokenを持ってきたら話を聞いてやる。\n\nそいつをその汚ねえ小さなひよっこの手に入れる方法は一つしかない――殺しまくってこい。", "<Commander Metzが葉巻を噛む。>\n\n何だ？俺は忙しい身なんだ。", "いいか、仕組みはこうだ。valor tokenを渡すたびに、別の令状をひとつ渡す。その令状に書かれた注文を揃えて、Packmaster Stonebruiserに届けるんだ。分かったか?よし。じゃあ、とっとと行け。", 0x29b5a92c, 0xfe328114, 0x27e4bb65, 0x652660a3, 0xf7b6fb79, "....." },
  [9153] = { "影の下で", "地図を確認し、Scourgeの攻撃を受けている地域を探す。そこへ行き、周囲のScourgeを倒してネクロポリスに損害を与える。彼らのNecrotic Runesを$N1個、Eastern PlaguelandsのLight's Hope ChapelにいるCommander Thomas Helleranのところへ持って行って下さい。", "Scourgeの浮遊する死霊の城塞は、HordeとAllianceの土地を等しく苦しめている。Tanaris、Blasted Lands、Winterspring、Burning Steppesは、空飛ぶ要塞の影にすっぽりと覆われている。\n\n我々が力を合わせてこそ、奴らを追い払えるのだ。\n\n死霊の城塞は、侵略された地域の各地にある魔法の円によって支えられている。その円を取り囲む心なき大群を倒せば、円の防御を崩せることが分かった。", "この脅威に打ち勝つには時間がかかる。首尾はどうだ、{name}?", "よくやった、{name}。こうした小さな勝利を積み重ねることで、再び迫るこのScourgeの脅威に我々は打ち勝つだろう。\n\n休んで回復するがいい。だがその後はまた前線へ向かわねばならん。今日得た地を失わぬためにな。\n\nこれからの戦いの助けとなるよう、necrotic runesと引き換えに、我々の特別な品をいくつか提供しよう。", 0x9e3cf3c9, 0x8c89f34b, 0x1788ecf5, 0x75ea4b6d, 0x0318842c, "....." },
  [9154] = { "Light's Hope Chapel", "Call to Arms AnnouncementをEastern PlaguelandsのLight's Hope ChapelにいるKeeper of the Rollsに届けて下さい。", "Scourgeが、かつてないほどの数で戻ってきた。Argent Dawnは、我らの土地を守るため、志があり力のある男女を一人残らず募っている。\n\n志を同じくするなら、この書状をEastern PlaguelandsのLight's Hope ChapelにいるKeeper of the Rollsのもとへ持っていってくれ。", "我らの教団に加わりに来たのだろう?", "Argent Dawnが援助を呼びかけ、君はほかの者たちとともにそれに応えてくれた。我々には君に訓練を施す時間はない。我々は君の力を信じている。そして君が、このScourgeの脅威を押し返す戦いに加わってくれることもな。", 0x0141f7a7, 0x3ddcc4ef, 0xf8db3513, 0xa0de5425, 0xb13b78e0, "....." },
  [9229] = { "Fate of Ramaladni", "Naxxramasに入り、Fate of Ramaladniを明らかにする。", "RamaladniはBrotherhoodのウォリアーだった――Dawnが生まれるよりも前の、Highlord Mograineの弟子だ！Mograineの死の知らせが届いたとき、彼は憎しみと怒りに呑まれた。\n\nこれを理解しておけ、{name}。怒りと報復が手綱を握ったとき、人は人でなくなる。そうではなく、自分を支配する感情そのものになるのだ。そうして報復の化身となったRamaladniはNaxxramasに入り、復讐を果たそうとした……そして二度と戻らなかった。\n\nNaxxramasに入り、Ramaladniがどうなったのか突き止めてくれ。", "Ramaladniの知らせは何かあったか?", "これは彼の指輪だ!だが壊れている。Ramaladniのほかの痕跡は見つからなかったのか?\n\n<Korfaxが顔をしかめる。>\n\nRamaladniにとって良い兆しではないな。だが指輪は……修復できるかもしれん。", 0xfd5b4cde, 0xc5d447bd, 0x281d620a, 0xb8524c1a, 0xd438d4ec, "....." },
  [9230] = { "Ramaladni's Icy Grasp", "Eastern PlaguelandsのLight's Hope ChapelにいるKorfaxは、Frozen Runeを$N1個、Blue Sapphireを$N2個、Arcanite Barを$N3個持ってきてほしいと言っています。", "この指輪を直すのはかなり骨が折れるかもしれないよ、{name}。というのも、これはScourgeの建造物――Naxxramasのような――の中で生まれるルーンそのものから作られているんだ。ほかにも材料が要るけど、一番気にかけるべきはそのfrozen runesを手に入れることさ。必要なものを持ってきてくれたら、指輪をかつての輝きに戻してあげるよ。", "Frozen runesはおそらくNaxxramasの中で見つかるだろう。", "Ramaladni本人でも、これ以上うまくはできなかっただろう!約束通り、指輪だ。", 0x1cbb7bc6, 0x4ee69506, 0x16dff9fa, 0x6e2af176, 0x6d0b2024, "....." },
  [9232] = { "知っている唯一の歌……", "Eastern PlaguelandsのLight's Hope ChapelにいるCraftsman Wilhelmは、Frozen Runesを$N1個、Essence of Waterを$N2個、Blue Sapphiresを$N3個、そして$N4ゴールドを持ってきてほしいと言っています。", "自分をDawnの英雄だとでも思ってるのか、え？うちの一番の兵士たちがKel'Thuzadの雑兵どもに轢き潰されるのを見てきたんだぞ！そんな何も分かってない奴が、Naxxramasでどこまでやれるってんだ？\n\n<Wilhelmはため息をつく。>\n\nちっ、他にどうしろってんだ？お前が俺にできる精一杯だ。手を貸してやるしかないな。\n\nOmarionが俺に残したレシピは一つだけだ。知ってる歌はそれだけってわけさ……このズボンの型違いをいくつか作れる。材料さえ持ってくりゃいい。", "Omarionには出くわしていないな?", "<Wilhelmが額の汗をぬぐう。>\n\nなかなかの重労働だった!そのズボンを楽しんでくれ、{class}。少なくとも、これで死ぬときは清潔なズボンを履いていられるぞ。", 0x519f4d00, 0x38b5bfde, 0x146036e1, 0x8ad23295, 0x2677e2a7, "....." },
  [9233] = { "Omarion's Handbook", "Omarion's HandbookをEastern PlaguelandsのLight's Hope ChapelにいるCraftsman Wilhelmのところへ持って行って下さい。", "Wilhelmへ\n\nこれを読んでいるなら、私は死んだということだ――ついにな。知っておいてほしいのだが、死にゆく私の思いは、お前と、生産技術に関するお前の無能さのことばかりだった。あいにく、この手引書を持ってきた者は、物作りに関してはお前よりさらにひどい有様だ。\n\nこの本について：これは私の残りのレシピだ。この本を持ってきた者が望むものは何でも作ってやれ。どうせお前は、自分の仕事に法外な代金を取るのだろうな。何しろお前はろくでなしなのだから。\n\n軽蔑をこめて\n\nOmarion", "それは私が思っている物か?\n\n<Wilhelmはよだれを垂らしているようだ。>", "これを書いた時、あいつは本当にどうかしてたに違いない!Omarionと俺は……大の仲良しだったんだ!\n\nともかく、これで新しい可能性が開けたのは確かだ、{name}。これで俺はもっと多くの品を作れるようになった。もちろん、わずかな手数料と材料費はいただくがな。", 0x5fd241d6, 0x0fa9fd4b, 0x7d852a96, 0xa5320578, 0xb4c95772, "....." },
  [9234] = { "Icebane Gauntlets", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 5つ・Thorium Bar 12本・Arcanite Bar 2本・Essence of Water 2つ・金貨200枚を要求しています。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでIcebane gauntletsを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0xb1ff7de5, 0x6c1d4b30, 0x26bc0f93, 0x0d86390a, 0xce411185, "....." },
  [9235] = { "Icebane Bracers", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 4つ・Thorium Bar 12本・Arcanite Bar 2本・Essence of Water 2つ・金貨200枚を要求しています。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでIcebane bracersを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0x63cca747, 0x1260a20e, 0xf077fcb1, 0x0d86390a, 0xce411185, "....." },
  [9236] = { "Icebane Breastplate", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 8つ・Thorium Bar 16本・Arcanite Bar 2本・Essence of Water 4つ・金貨300枚を要求しています。Argent Dawnの評判が賛美(Exalted)でなければなりません。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでIcebane breastplateを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0x4e2bceaa, 0xfc110014, 0xa8b406d7, 0x0d86390a, 0xce411185, "....." },
  [9237] = { "Glacial Cloak", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 5つ・Bolt of Runecloth 4本・Essence of Water 2つ・Ironweb Spider Silk 4つ・金貨200枚を要求しています。Argent Dawnの評判が賛美(Exalted)でなければなりません。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでGlacial cloakを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0x18004bb0, 0x1f37eaae, 0x4cb81801, 0x0d86390a, 0xce411185, "....." },
  [9238] = { "Glacial Wrists", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 4つ・Bolt of Runecloth 2本・Essence of Water 2つ・Ironweb Spider Silk 2つ・金貨200枚を要求しています。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでGlacial wristsを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", nil, "こんなに早くその顔を見るとは思っていなかった。\n\nこれは実に良い知らせだ。{name}、君が想像する以上に、いろいろな意味でな。", 0x5705d3c0, 0xc3e58102, 0xc5358afd, nil, 0x9f82796e, "...m." },
  [9239] = { "Glacial Gloves", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 5つ・Bolt of Runecloth 4本・Essence of Water 4つ・Ironweb Spider Silk 2つ・金貨200枚を要求しています。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでGlacial glovesを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0x363d66ea, 0xba017235, 0x3792ae76, 0x0d86390a, 0xce411185, "....." },
  [9240] = { "Glacial Vest", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 8つ・Bolt of Runecloth 8本・Essence of Water 6つ・Ironweb Spider Silk 4つ・金貨300枚を要求しています。Argent Dawnの評判が賛美(Exalted)でなければなりません。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでGlacial vestを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0xd3d23e1b, 0xcd82a11e, 0xc8a26e31, 0x0d86390a, 0xce411185, "....." },
  [9241] = { "Polar Bracers", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 4つ・Enchanted Leather 12枚・Essence of Water 3つ・Cured Rugged Hide 3枚・金貨200枚を要求しています。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでPolar bracersを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0x1f8f20b8, 0xab2116f4, 0xdd632e6d, 0x0d86390a, 0xce411185, "....." },
  [9242] = { "Polar Gloves", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 5つ・Enchanted Leather 12枚・Essence of Water 3つ・Cured Rugged Hide 3枚・金貨200枚を要求しています。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでPolar glovesを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0x5d44dfe7, 0xabe000a3, 0x37e5653d, 0x0d86390a, 0xce411185, "....." },
  [9243] = { "Polar Tunic", "Eastern PlaguelandsのLight's Hope ChapelにいるCraftsman Wilhelmは、Frozen Runeを8個、Enchanted Leatherを16個、Essence of Waterを5個、Cured Rugged Hideを5個、そして300ゴールドを求めています。また、Argent Dawnとの評判がExaltedである必要があります。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでPolar tunicを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0xf3cae379, 0x12afca90, 0x53e4dd23, 0x0d86390a, 0xce411185, "....." },
  [9244] = { "Icy Scale Bracers", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 4つ・Heavy Scorpid Scale 16枚・Essence of Water 5つ・Cured Rugged Hide 3枚・金貨200枚を要求しています。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでIcy Scale bracersを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0x45ec600c, 0xf7e17196, 0x48900b51, 0x0d86390a, 0xce411185, "....." },
  [9245] = { "Icy Scale Gauntlets", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 5つ・Heavy Scorpid Scale 16枚・Essence of Water 5つ・Cured Rugged Hide 3枚・金貨200枚を要求しています。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでIcy Scale gauntletsを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0xf27864b3, 0xcb09217c, 0x92db9c3b, 0x0d86390a, 0xce411185, "....." },
  [9246] = { "Icy Scale Breastplate", "Eastern PlaguelandsにあるLight's Hope ChapelのCraftsman Wilhelmは、Frozen Rune 8つ・Heavy Scorpid Scale 24枚・Essence of Water 7つ・Cured Rugged Hide 5枚・金貨300枚を要求しています。Argent Dawnの評判が賛美(Exalted)でなければなりません。", "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでIcy Scale breastplateを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。", "材料は持ってきたか?", "注文の品だ、{name}。約束通りの納品だ!", 0x36d42a52, 0xee8d4219, 0xe98d75d0, 0x0d86390a, 0xce411185, "....." },
  [9247] = { "守り手の召集", "Letter from the Keeper of the Rollsを、Eastern PlaguelandsのLight's Hope Chapelにいる彼のもとへ届けてください。", "{name}へ\n\nこれまであなたは、常に全力を尽くしてArgent Dawnの利益のために尽くしてくれました。今、最大の危機にあたって、我々は再び召集のラッパを鳴らします。\n\n{name}、もう一度我々に力を貸してくださるなら、Eastern PlaguelandsのLight's Hope ChapelにいるKeeper of the Rollsのもとへ出頭してください。", nil, nil, 0xe8f9010e, 0x24d23469, 0x455bb082, nil, nil, "...mm" },
  [9248] = { "ささやかな捧げ物", "SilithusのCenarion HoldにいるAurel Goldleafは、Abyssal Scepterを1本持ってくるよう求めています。また、Cenarion Circleの評判が尊敬(Honored)でなければなりません。", "あなたに良き幸運を、{race}。Abyssal Councilの王が死んだ証を見せて下さい。そうしたら、Qirajiとの戦いに役立つ品を報酬として差し上げましょう。", "Fandu-dath-belore? ああ、失礼しました、{name}。あなただと気づきませんでした。scepterはお持ちですか?", "Ande'thoras-ethil。私の故郷の言葉で、「あなたの悩みが少なくなりますように」という意味です。\n\nその指輪を誇りを持って、健やかに身に着けてください、{name}。", 0xfd579dde, 0xcb666c32, 0x5dee4073, 0x6b22398a, 0x4faf4b72, "....." },
  [9250] = { "Frame of Atiesh", "杖の残り2パーツの回収と邪気払いに力を貸してくれる者を見つける。", "枠が形になり、Atieshはほぼ完全な姿を取り戻した。欠けているのは杖の頭部と基部だけだ。また、この杖がSargerasの邪悪の通り道になっているという、ちょっとした問題もある。\n\n残りの部品を探し出し、杖から邪悪を祓うのを手伝ってくれる者を見つけるのだ。", "あれの時が来たのだ、定命の者よ。", "大魔導師たちは死んだ。\n\n彼らの死を悼むことはない、{name}。このようなことはすべて定められていたのだ。そなたが守護者の杖を手にすることが定められていたように……", 0xf653c43a, 0x408b91b7, 0x2be6e916, 0x6bb260cc, 0xebb1066f, "....." },
  [9251] = { "穢された大杖 Atiesh", "Tanaris の Caverns of Time にいる Anachronos は Staff Head of Atiesh ・ Base of Atiesh を求めている。", "なぜ己がまだ生きているのかと問うたな。何しろ、そなたはとてつもなく邪悪な物を所有しているのだ。 {name}、答えは「分からぬ」だ。我は己がなすべきことをするのみ。Kel'Thuzad は Naxxramas にある玉座に座り、策を練っている……そなたの探し物はあやつが持っている。あやつもまた、そなたの持っている物を求めている。杖の石突きに関しては、ドワーフの Brann Bronzebeard が Ahn'Qiraj に入った時に手にした。Brann Bronzebeard は Ahn'Qiraj から出たが、Atiesh の石突きはそのまま残されている。首尾良く部品を集めたならば、我のもとへ持ってくるがよい。", "今の形のままでは、その杖は定命の者の手にあるにはあまりに危険だ。", "中に何者かがいる……この世のものならぬ何者かが。", 0xcd0ba26f, 0xd3abd03c, 0xf57ef0e6, 0x6141889a, 0x8e96d632, "....." },
  [9257] = { "Atiesh, Greatstaff of the Guardian", "Tanaris の Caverns of Time にいる Anachronos は、Atiesh, Greatstaff of the Guardian を Stratholme へ持っていき聖地の上で使うよう求めている。杖から払われた実体を倒し、Anachronos に杖を渡す。", "{name} よ、最後の仕事は最も困難だ。そなたは Old God と Lich King の将軍にまみえ両者とも倒したが、今度は「 Sargeras の手」と対峙せねばならぬ。この杖を Stratholme へ持っていけ。聖地―― Lordaeron 最高の騎士が殺害された場所が見つかるであろう。この穢された杖を聖地に置き、中から現れる莫大な力の実体に備えよ……杖を操っていた悪魔を倒し、我のもとへ持ち帰るのだ。", "私が干渉するわけにはいかぬのだ、{race}。", "この偉業の大きさを、決して過小評価してはならぬ、{name}。そなたは、ほとんどの者が不可能と考えたであろうことを成し遂げたのだ。だが、それは定められていたこと。杖は選択を下したのだ……", 0x9b7c702f, 0xc82f289b, 0xe69efe9d, 0x6241b6f1, 0xc81ee3eb, "....." },
  [9260] = { "StormwindのScourgeの調査", "Stormwindの外にいるScourgeからDim Necrotic Stoneを3個集め、彼らの野営地の近くにある光るルーンの円陣を調べてください。", "Scourgeがまさに我らの戸口に陣を張っている。手をこまねいているわけにはいかん！ お前ならきっと、この呪われた侵略者どもからStormwindを守るために立ち上がってくれるだろう？\n\n外には奇妙なルーンの円陣があって、アンデッドや上空のNecropolisを取り巻いているのと同じエネルギーを放って光っている。あれには意味があるはずだ。それが何なのか突き止めてほしい。ついでにあの化け物どもの数を減らしてこい。調べた結果と一緒に奴らを倒した証拠を持ってくれば、報酬を与えよう。行け！", "もう侵攻について調べたか? ぐずぐずしている暇はないぞ!", "ふむ。君の話からすると、円陣の中の声は……何らかの交信に使われているに違いない。あのような魔術でどんな不自然な精神と通じているのか、考えるだけで身震いする。いずれにせよ、君は無事で正気のまま戻ってきたようだ。Argent Dawnは君の尽力に感謝する。", 0x00e4dbef, 0x9dc15400, 0x584b0283, 0x5ea2db66, 0x4f3229e9, "....." },
  [9261] = { "IronforgeのScourgeの調査", "Ironforgeの外にいるScourgeからDim Necrotic Stoneを3個集め、彼らの野営地の近くにある光るルーンの円陣を調べてください。", "Scourgeがまさに我らの戸口に陣を張っている。手をこまねいているわけにはいかん！ お前ならきっと、この呪われた侵略者どもからIronforgeを守るために立ち上がってくれるだろう？\n\n外には奇妙なルーンの円陣があって、アンデッドや上空のNecropolisを取り巻いているのと同じエネルギーを放って光っている。あれには意味があるはずだ。それが何なのか突き止めてほしい。ついでにあの化け物どもの数を減らしてこい。調べた結果と一緒に奴らを倒した証拠を持ってくれば、報酬を与えよう。行け！", "もう侵攻について調べたか? ぐずぐずしている暇はないぞ!", "ふむ。君の話からすると、円陣の中の声は……何らかの交信に使われているに違いない。あのような魔術でどんな不自然な精神と通じているのか、考えるだけで身震いする。いずれにせよ、君は無事で正気のまま戻ってきたようだ。Argent Dawnは君の尽力に感謝する。", 0x71257d44, 0x40d576b1, 0x6d9b70a9, 0x5ea2db66, 0x4f3229e9, "....." },
  [9262] = { "DarnassusのScourgeの調査", "Darnassusの外にいるScourgeからDim Necrotic Stoneを3個集め、彼らの野営地の近くにある光るルーンの円陣を調べてください。", "Scourgeがまさに我らの戸口に陣を張っている。手をこまねいているわけにはいかん！ お前ならきっと、この呪われた侵略者どもからDarnassusを守るために立ち上がってくれるだろう？\n\n外には奇妙なルーンの円陣があって、アンデッドや上空のNecropolisを取り巻いているのと同じエネルギーを放って光っている。あれには意味があるはずだ。それが何なのか突き止めてほしい。ついでにあの化け物どもの数を減らしてこい。調べた結果と一緒に奴らを倒した証拠を持ってくれば、報酬を与えよう。行け！", "もう侵攻について調べたか? ぐずぐずしている暇はないぞ!", "ふむ。君の話からすると、円陣の中の声は……何らかの交信に使われているに違いない。あのような魔術でどんな不自然な精神と通じているのか、考えるだけで身震いする。いずれにせよ、君は無事で正気のまま戻ってきたようだ。Argent Dawnは君の尽力に感謝する。", 0xae0b4b57, 0x8c429383, 0x2683cc59, 0x5ea2db66, 0x4f3229e9, "....." },
  [9263] = { "OrgrimmarのScourgeの調査", "Orgrimmarの外にいるScourgeからDim Necrotic Stonesを三つ集め、彼らの野営地の近くにある光るルーンの円を調べる。", "Scourgeがまさに我らの目と鼻の先に陣取っている。黙って見ているわけにはいかん！この忌まわしい侵略者どもからOrgrimmarを守るため、当然お前は名乗り出てくれるな？\n\n外には奇妙なルーンの円がいくつもあって、アンデッドと上空のNecropolisを包むのと同じ力で輝いている。何か意味があるのは確かだ。それが何なのかを突き止めてもらいたい。ついでにあの化け物どもの数も減らしてこい。調べた結果と一緒に奴らを倒した証を持ってくれば、褒美をやろう。行け！", "もう侵攻について調べたか? ぐずぐずしている暇はないぞ!", "ふむ。君の話からすると、円陣の中の声は……何らかの交信に使われているに違いない。あのような魔術でどんな不自然な精神と通じているのか、考えるだけで身震いする。いずれにせよ、君は無事で正気のまま戻ってきたようだ。Argent Dawnは君の尽力に感謝する。", 0xa887c042, 0xed596569, 0x4535136d, 0x5ea2db66, 0x4f3229e9, "....." },
  [9264] = { "Thunder BluffのScourgeの調査", "Thunder Bluffの外にいるScourgeからDim Necrotic Stonesを三つ集め、彼らの野営地の近くにある光るルーンの円を調べる。", "Scourgeがまさに我らの目と鼻の先に陣取っている。黙って見ているわけにはいかん！この忌まわしい侵略者どもからThunder Bluffを守るため、当然お前は名乗り出てくれるな？\n\n外には奇妙なルーンの円がいくつもあって、アンデッドと上空のNecropolisを包むのと同じ力で輝いている。何か意味があるのは確かだ。それが何なのかを突き止めてもらいたい。ついでにあの化け物どもの数も減らしてこい。調べた結果と一緒に奴らを倒した証を持ってくれば、褒美をやろう。行け！", "もう侵攻について調べたか? ぐずぐずしている暇はないぞ!", "ふむ。君の話からすると、円陣の中の声は……何らかの交信に使われているに違いない。あのような魔術でどんな不自然な精神と通じているのか、考えるだけで身震いする。いずれにせよ、君は無事で正気のまま戻ってきたようだ。Argent Dawnは君の尽力に感謝する。", 0xa9531e97, 0x64454a5d, 0xb814786e, 0x5ea2db66, 0x4f3229e9, "....." },
  [9265] = { "UndercityのScourgeの調査", "Undercityの外にいるScourgeからDim Necrotic Stonesを三つ集め、彼らの野営地の近くにある光るルーンの円を調べる。", "Scourgeがまさに我らの目と鼻の先に陣取っている。黙って見ているわけにはいかん！この忌まわしい侵略者どもからUndercityを守るため、当然お前は名乗り出てくれるな？\n\n外には奇妙なルーンの円がいくつもあって、アンデッドと上空のNecropolisを包むのと同じ力で輝いている。何か意味があるのは確かだ。それが何なのかを突き止めてもらいたい。ついでにあの化け物どもの数も減らしてこい。調べた結果と一緒に奴らを倒した証を持ってくれば、褒美をやろう。行け！", "もう侵攻について調べたか? ぐずぐずしている暇はないぞ!", "ふむ。君の話からすると、円陣の中の声は……何らかの交信に使われているに違いない。あのような魔術でどんな不自然な精神と通じているのか、考えるだけで身震いする。いずれにせよ、君は無事で正気のまま戻ってきたようだ。Argent Dawnは君の尽力に感謝する。", 0xe8ce843e, 0xae694c31, 0xcdb468ae, 0x5ea2db66, 0x4f3229e9, "....." },
  [9269] = { "Atiesh, Greatstaff of the Guardian", "Tanaris の Caverns of Time にいる Anachronos は、Atiesh, Greatstaff of the Guardian を Stratholme へ持っていき聖地の上で使うよう求めている。杖から払われた実体を倒し、Anachronos に杖を渡す。", "{name} よ、最後の仕事は最も困難だ。そなたは Old God と Lich King の将軍にまみえ両者とも倒したが、今度は「 Sargeras の手」と対峙せねばならぬ。この杖を Stratholme へ持っていけ。聖地―― Lordaeron 最高の騎士が殺害された場所が見つかるであろう。この穢された杖を聖地に置き、中から現れる莫大な力の実体に備えよ……杖を操っていた悪魔を倒し、我のもとへ持ち帰るのだ。", "私が干渉するわけにはいかぬのだ、{race}。", "この偉業の大きさを、決して過小評価してはならぬ、{name}。そなたは、ほとんどの者が不可能と考えたであろうことを成し遂げたのだ。だが、それは定められていたこと。杖は選択を下したのだ……", 0x9b7c702f, 0xc82f289b, 0xe69efe9d, 0x6241b6f1, 0xc81ee3eb, "....." },
  [9270] = { "Atiesh, Greatstaff of the Guardian", "Tanaris の Caverns of Time にいる Anachronos は、Atiesh, Greatstaff of the Guardian を Stratholme へ持っていき聖地の上で使うよう求めている。杖から払われた実体を倒し、Anachronos に杖を渡す。", "{name} よ、最後の仕事は最も困難だ。そなたは Old God と Lich King の将軍にまみえ両者とも倒したが、今度は「 Sargeras の手」と対峙せねばならぬ。この杖を Stratholme へ持っていけ。聖地―― Lordaeron 最高の騎士が殺害された場所が見つかるであろう。この穢された杖を聖地に置き、中から現れる莫大な力の実体に備えよ……杖を操っていた悪魔を倒し、我のもとへ持ち帰るのだ。", "私が干渉するわけにはいかぬのだ、{race}。", "この偉業の大きさを、決して過小評価してはならぬ、{name}。そなたは、ほとんどの者が不可能と考えたであろうことを成し遂げたのだ。だが、それは定められていたこと。杖は選択を下したのだ……", 0x9b7c702f, 0xc82f289b, 0xe69efe9d, 0x6241b6f1, 0xc81ee3eb, "....." },
  [9271] = { "Atiesh, Greatstaff of the Guardian", "Tanaris の Caverns of Time にいる Anachronos は、Atiesh, Greatstaff of the Guardian を Stratholme へ持っていき聖地の上で使うよう求めている。杖から払われた実体を倒し、Anachronos に杖を渡す。", "{name} よ、最後の仕事は最も困難だ。そなたは Old God と Lich King の将軍にまみえ両者とも倒したが、今度は「 Sargeras の手」と対峙せねばならぬ。この杖を Stratholme へ持っていけ。聖地―― Lordaeron 最高の騎士が殺害された場所が見つかるであろう。この穢された杖を聖地に置き、中から現れる莫大な力の実体に備えよ……杖を操っていた悪魔を倒し、我のもとへ持ち帰るのだ。", "私が干渉するわけにはいかぬのだ、{race}。", "この偉業の大きさを、決して過小評価してはならぬ、{name}。そなたは、ほとんどの者が不可能と考えたであろうことを成し遂げたのだ。だが、それは定められていたこと。杖は選択を下したのだ……", 0x9b7c702f, 0xc82f289b, 0xe69efe9d, 0x6241b6f1, 0xc81ee3eb, "....." },
  [9272] = { "相応しい装い", nil, nil, nil, "ヤーーーー……我々経験豊富な海賊仲間とのお楽しみに没頭しているんだったら、ならず者みてえな格好はやめた方がいいぜ! ほらよ、こっぴどく叱られる前にちゃんとしたもんを着ろ。\n\nRed-Eyed Ben が着るよりお前の方がずっと似合うだろ。悪魔みてえな大しけの時にあいつとはぐれちまったんだ。\n\n誇りを持って着ろよ、相棒!", 0x09338667, nil, nil, nil, 0x35e4428b, ".mmm." },
  [9273] = { "iCoke Prize Voucherを引き換える", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [9292] = { "Cracked Necrotic Crystal", "Cracked Necrotic Crystalを、Stormwindの門の外にいるLieutenant Orrinのところへ持って行ってください。", "倒れたabominationの死骸から、死のエネルギーでゆっくりと脈打つ、ひび割れた水晶が見つかった。", "何か入り用かね?", "ふむ、これを侵入してきたabominationsの1体の死体から取ってきたのか?\n\nScourgeが召喚しているネクロポリスの拠点について、知らせを受けている。奴らはStormwindの中にもそれを作ろうとしていたのだろう。失敗に終わったのは幸いだ。", 0x50e85762, 0x78ac8cb0, 0xfb485a40, 0x05240edc, 0x92f243ce, "....." },
  [9295] = { "Letter from the Front", "Torn LetterをEastern PlaguelandsのLight's Hope ChapelにいるKeeper of the Rollsのところへ持って行って下さい。", "あなたが倒した数多くのScourgeの手下の一体から、この手紙が見つかった。見た目と臭いからすると、かなり長いあいだアンデッドの手元にあったようだ。Light's Hope Chapelの誰かなら、詳しく調べることに興味を示すかもしれない……", "うん? そこに持っているのは何だ?", "なんと痛ましい。この言葉は明らかに、兵士が愛した誰かに宛てたものなのに、届くことはなかったのですね。書かれている出来事は何年も前のこと。受け取るはずだった人がまだ生きているかどうかは分かりません。\n\nですが、まだ望みはあります。彼が記した名前や情報を使えば、家族を見つけ出せるかもしれません!調べるのに時間はかかるでしょうが、Stormwindの司書には貸しがあるのです……\n\nこれを届けてくださってありがとうございます。あなたのおかげで、ようやく誰かに心の平安を与えられるかもしれません。", 0x96157b4a, 0xc88064df, 0x43325f84, 0xf8d5b5af, 0xf0bfe43f, "....." },
  [9299] = { "前線からの覚え書き", "Careworn NoteをEastern PlaguelandsのLight's Hope ChapelにいるKeeper of the Rollsのところへ持って行って下さい。", "あなたが倒した数多くのScourgeの手下の一体から、この手紙が見つかった。見た目と臭いからすると、かなり長いあいだアンデッドの手元にあったようだ。Light's Hope Chapelの誰かなら、詳しく調べることに興味を示すかもしれない……", "うん? そこに持っているのは何だ?", "なんと痛ましい。この言葉は明らかに、兵士が愛した誰かに宛てたものなのに、届くことはなかったのですね。書かれている出来事は何年も前のこと。受け取るはずだった人がまだ生きているかどうかは分かりません。\n\nですが、まだ望みはあります。彼が記した名前や情報を使えば、家族を見つけ出せるかもしれません!調べるのに時間はかかるでしょうが、Stormwindの司書には貸しがあるのです……\n\nこれを届けてくださってありがとうございます。あなたのおかげで、ようやく誰かに心の平安を与えられるかもしれません。", 0xe162fd2c, 0xeb1d0cfc, 0x43325f84, 0xf8d5b5af, 0xf0bfe43f, "....." },
