  [9301] = { "前線からの封筒", "Bloodstained EnvelopeをEastern PlaguelandsのLight's Hope ChapelにいるKeeper of the Rollsのところへ持って行って下さい。", "あなたが倒した数多くのScourgeの手下の一体から、この手紙が見つかった。見た目と臭いからすると、かなり長いあいだアンデッドの手元にあったようだ。Light's Hope Chapelの誰かなら、詳しく調べることに興味を示すかもしれない……", "うん? そこに持っているのは何だ?", "なんと痛ましい。この言葉は明らかに、兵士が愛した誰かに宛てたものなのに、届くことはなかったのですね。書かれている出来事は何年も前のこと。受け取るはずだった人がまだ生きているかどうかは分かりません。\n\nですが、まだ望みはあります。彼が記した名前や情報を使えば、家族を見つけ出せるかもしれません!調べるのに時間はかかるでしょうが、Stormwindの司書には貸しがあるのです……\n\nこれを届けてくださってありがとうございます。あなたのおかげで、ようやく誰かに心の平安を与えられるかもしれません。", 0x1fd6ec00, 0x39b36052, 0x43325f84, 0xf8d5b5af, 0xf0bfe43f, "....." },
  [9302] = { "前線からの書状", "Crumpled MissiveをEastern PlaguelandsのLight's Hope ChapelにいるKeeper of the Rollsのところへ持って行って下さい。", "あなたが倒した数多くのScourgeの手下の一体から、この手紙が見つかった。見た目と臭いからすると、かなり長いあいだアンデッドの手元にあったようだ。Light's Hope Chapelの誰かなら、詳しく調べることに興味を示すかもしれない……", "うん? そこに持っているのは何だ?", "なんと痛ましい。この言葉は明らかに、兵士が愛した誰かに宛てたものなのに、届くことはなかったのですね。書かれている出来事は何年も前のこと。受け取るはずだった人がまだ生きているかどうかは分かりません。\n\nですが、まだ望みはあります。彼が記した名前や情報を使えば、家族を見つけ出せるかもしれません!調べるのに時間はかかるでしょうが、Stormwindの司書には貸しがあるのです……\n\nこれを届けてくださってありがとうございます。あなたのおかげで、ようやく誰かに心の平安を与えられるかもしれません。", 0xd5e14e2f, 0xdc92c168, 0x43325f84, 0xf8d5b5af, 0xf0bfe43f, "....." },
  [9304] = { "前線からの文書", "Smudged DocumentをEastern PlaguelandsのLight's Hope ChapelにいるKeeper of the Rollsのところへ持って行って下さい。", "あなたが倒した数多くのScourgeの手下の一体から、この手紙が見つかった。見た目と臭いからすると、かなり長いあいだアンデッドの手元にあったようだ。Light's Hope Chapelの誰かなら、詳しく調べることに興味を示すかもしれない……", "うん? そこに持っているのは何だ?", "なんと痛ましい。この言葉は明らかに、兵士が愛した誰かに宛てたものなのに、届くことはなかったのですね。書かれている出来事は何年も前のこと。受け取るはずだった人がまだ生きているかどうかは分かりません。\n\nですが、まだ望みはあります。彼が記した名前や情報を使えば、家族を見つけ出せるかもしれません!調べるのに時間はかかるでしょうが、Stormwindの司書には貸しがあるのです……\n\nこれを届けてくださってありがとうございます。あなたのおかげで、ようやく誰かに心の平安を与えられるかもしれません。", 0xabec2052, 0xe8881a90, 0x43325f84, 0xf8d5b5af, 0xf0bfe43f, "....." },
  [9310] = { "Faint Necrotic Crystal", "Faint Necrotic CrystalをUndercityの中庭にいるLieutenant Rukagのところへ持って行って下さい。", "倒れたwightの死骸から、かすかに死霊の力を放つ水晶が見つかった。", "何かご用かな?", "街を襲っていたwightからこれを奪ったというのか?\n\nScourgeが召喚しているネクロポリスの拠点について、知らせを受けている。奴らはUndercityの中にそれを作ろうとしていたのだろう。今後は警戒を怠らぬようにせねばならん。", 0xe2cc3f91, 0x78a121b3, 0x83ff7c6c, 0xc8eedeb3, 0x57dd511f, "....." },
  [9319] = { "暗き場所の光", "Blackrock Spire、Dire Maul、Scholomance、Stratholmeの中にあるかがり火を見つけて触れ、Festival Flamekeeperのところへ戻って下さい。", "この祭りを祝うのは我々だけではありません、{name}。あらゆる生き物、あらゆる文化が、炎に触れているのです。最も暗い場所でさえ、火が灯されつつあります。\n\n自分の目で確かめたいなら、深みへと旅してください。Stratholme、Scholomance、Dire Maulのogresのもと、そしてBlackrock Spireの広間そのものの中で燃えるかがり火を探し出すのです。あなたの帰りを待っていますよ。", "闇の中を進む道は見つかったか?", "{name}、あなたの本質は、見つけた炎の力で歌うように震えています。あなたが出会った火は強力で、正しい知識があれば、その力を役立てることができるのです……\n\n<炎の守り手は奇妙な秘術の言葉で呪文をつぶやき、それから光る瓶を取り出す。>\n\nああ!ありました。どこを歩もうとも、これがあなたの道を照らしますように。", 0xc7993864, 0x71f9855e, 0x22e1d9d3, 0x6fd59256, 0xb63b325f, "....." },
  [9322] = { "Kalimdorの野火", "Azshara、Silithus、Un'Goro Crater、WinterspringにあるMidsummerのキャンプを訪れ、Festival Flamekeeperのところへ戻ってください。", "Midsummer Fire FestivalはAzerothのいたるところで祝われていて、多様な地Kalimdorも例外じゃない。旅ができそうな様子だね――ひとつ旅に出てみるのもいいかもしれない。\n\n各地で燃え盛る青い炎を見なければ、Midsummerの本当の良さは分からない。祝う人々は、寒い西のWinterspring、北東のAzshara、Silithusの荒れ地にあるValor's Restの近く、そして緑豊かなUn'Goroの入口のそばに火を灯したんだ。旅を終えたら戻っておいで。", "Kalimdorの炎は明るく燃えているか?", "あなたの魂はKalimdorの炎の温もりで輝いていますね、友よ。その熱は活力を与えてくれるでしょう?\n\nその力があなたから消えたら、これがその感覚を再び灯す助けになるかもしれません。", 0x515e7ab2, 0x3a2cca60, 0xdeb42c6f, 0xe9989baa, 0x1254be4d, "....." },
  [9323] = { "Eastern Kingdomsの野火", "Blasted Lands、Eastern Plaguelands、Hinterlands、Searing GorgeにあるFire Festivalのキャンプを訪れ、Festival Flamekeeperと話してください。", "我らの炎の祭りは、この地のいたるところに広がっているんだ、{class}。この祝祭の熱が届いていない場所は一つもないし、最も強い火は鮮やかな青に燃える。それを探し出すんだ。\n\n一つはBlackrock Spireのすぐ北にある。他のは、Eastern Plaguelandsの奥深くの荒れ果てた町の近く、山がちなHinterlandsの崖へ続く道沿い、そしてBlasted LandsのDark Portalへ向かう途中にある。\n\n旅を終えたら戻っておいで。", "もう大陸を旅して回ったか? 悟りが君を待っている。", "ああ、戻りましたね。少し疲れて、少し埃っぽくなって、でも悟りを得て!この季節、熱は私たち皆に触れ、私たちを一つにします。あなたの存在そのものが、触れてきた炎の力で輝いていますよ。\n\nああ、でも近頃は、用事を言いつけられた報酬が悟りでは物足りないと思われるのでしょうね。では、これを受け取って、祭りを楽しんでください。", 0xb359bc1c, 0x1068f8e8, 0x3aadd8f0, 0x12c78f6d, 0x04028424, "....." },
  [9324] = { "Orgrimmarの炎の盗み", "Flame of OrgrimmarをFestival Loremasterに返却して下さい。", "Orgrimmarの中心から盗まれたこの炎は、あなたを炎熱で満たした。その荒々しい力には馴染みがないが、Loremasterならば詳しく知っているかもしれない……。", "まるで輝いているようだな、{race}。そこに持っているのは何だ?", "何でしょうこれは? 間違いでなければ、この炎はOrgrimmarそのものの中心から持ってこられたのですね! この火の焼け付くような熱に、オークやトロルたちの獰猛な魂が現れています。私たちの収集品に相応しい、なんて素晴らしい品なんでしょう。……敵の巣窟へ忍び込んで神聖な炎を手に入れてくるとは、なんと勇敢なことでしょう!", 0x6060e294, 0x2c3b06e5, 0xa233ef98, 0x35bceb01, 0xb78afa9a, "....." },
  [9325] = { "Thunder Bluffの炎の盗み", "Flame of Thunder BluffをFestival Loremasterに返却して下さい。", "Thunder Bluffのシャーマンから盗まれたこの炎は、あなたを炎熱で満たした。その荒々しい力には馴染みがないが、Loremasterならば詳しく知っているかもしれない……。", "まるで輝いているようだな、{race}。そこに持っているのは何だ?", "私の見立てが外れていなければ、この炎はThunder Bluffの崖から奪われたものですね! なんと精霊の力を帯びて歌っていることでしょう! あなたはなかなかの盗人ですよ、{name}。その腕前への正当な報酬として、これを受け取ってください。あとは、3つの都市すべての炎さえ揃えば……", 0xd6d267fd, 0x4526bcd9, 0x4d8c9c93, 0x35bceb01, 0x94adecd4, "....." },
  [9326] = { "Undercityの炎の盗み", "Flame of the UndercityをFestival Loremasterに返却して下さい。", "Undercityの上にある廃墟から盗まれたこの炎は、あなたを炎熱で満たした。その荒々しい力には馴染みがないが、Loremasterならば詳しく知っているかもしれない……。", "まるで輝いているようだな、{race}。そこに持っているのは何だ?", "ふむ……なんと奇妙な炎でしょう! 弱々しく、くすぶりかけているのに、熱はすさまじい。しかも、これをUndercityから受け取ったとおっしゃるのですか? 実に興味深い。3つの都市すべての炎が揃えば、どれほどのことが成し遂げられるでしょうね?", 0x65e82239, 0x889a7f0a, 0xdcc8620d, 0x35bceb01, 0x7a708213, "....." },
  [9330] = { "Stormwindの炎の盗み", "Flame of StormwindをFestival Talespinnerに返却して下さい。", "Stormwindの中心から盗まれたこの炎は、あなたを炎熱で満たした。その荒々しい力には馴染みがないが、Talespinnerならば詳しく知っているかもしれない……。", "まるで輝いているようだな、{race}。そこに持っているのは何だ?", "して、この赤々と燃える火……Stormwindから持ってきたのだと言いましたか? なんと目覚ましい! まさしく冒険だったことでしょう! 対価としてお支払いしますよ、もちろん。もし他にもこのようなものを見つけたら、必ず私に話して下さいね。", 0xba6f08b3, 0xf51d4d42, 0xca4b7ab5, 0x35bceb01, 0xfaa39f41, "....." },
  [9331] = { "Ironforgeの炎の盗み", "Flame of IronforgeをFestival Talespinnerに返却して下さい。", "Ironforgeの中心から盗まれたこの炎は、あなたを炎熱で満たした。その荒々しい力には馴染みがないが、Talespinnerならば詳しく知っているかもしれない……。", "まるで輝いているようだな、{race}。そこに持っているのは何だ?", "この力強い炎はIronforgeの広間から来たに違いありません。ドワーフ自身のように屈強ですからね。素晴らしい収穫ですよ、{name}。他の街の火も手に入れたら……あ、お気になさらず。これはお代ですよ。", 0x73da389b, 0x666a0263, 0x2834c54e, 0x35bceb01, 0xc94925a5, "....." },
  [9332] = { "Darnassusの炎の盗み", "Flame of DarnassusをFestival Talespinnerに返却して下さい。", "Teldrassilの海岸から盗まれたこの炎は、あなたを炎熱で満たした。その荒々しい力には馴染みがないが、Talespinnerならば詳しく知っているかもしれない……。", "まるで輝いているようだな、{race}。そこに持っているのは何だ?", "この炎は古代の悲しみに痛みを感じているのです、{name}。これをTeldrassilの根から取ってきたと言いましたね? 実に興味深い! これはあなたの腕前に対する報酬です。このようなものを見つけたならば、私のところへ持ってきて下さい。これの利用法があるかもしれませんので。", 0xadc93958, 0xbcda68cb, 0x50a8cf42, 0x35bceb01, 0xbdfd99a7, "....." },
  [9339] = { "盗人の報酬", "Flame of Stormwindを(NAME)のところへ返して下さい。", "Stormwindの中心そのものから盗まれたこの炎は、あなたを温もりで満たす。この生の力はあなたにとって未知のものだが、(NAME)なら何か知っているかもしれない……", nil, "{name}、今日あなたは実力を示しました。\n\n差し上げられるものはあまりありませんが、覇者に相応しい冠ならあります。これがあなたの進む道を照らしますように。", 0x6fd2503e, 0x9e249500, 0xc3ca99b1, nil, 0xe7fe3c18, "...m." },
  [9353] = { "iCoke Gift Box Voucherを引き換える", nil, nil, nil, nil, 0xcf2bfa37, nil, nil, nil, nil, ".mmmm" },
  [9362] = { "Warlord Krellian", "Archmage XylemのためにPrismatic Shellを取り戻して下さい。彼はAzsharaの崖上の塔に住んでいます。", "あまり時間が無い、{name}! 物見の魔法で、強い魔力の源が暴き出せたぞ。私はこの塔から離れられん。だから、この秘宝を持っている忌まわしい生き物を殺してもらえないだろうか。この哀れでちっぽけな卑怯者は、Temple of Zin-Malorで護衛に守られて隠れているWarlord Krellianとして知られている。Krellianを灰になるまで燃やし尽くし、こいつが大層大事にしているprismatic shellを手に入れてくれ。", "無駄にする時間はない! shellは手に入れたか?", "この貝殻には実に異常なオーラがある。これを取り戻してくれた報酬の一部としては、貝殻の魔法能力を試すことこそが相応しいようだな……", 0x724d1d5a, 0xe0e3c89c, 0x516377b1, 0xc66db138, 0x0c159361, "....." },
  [9364] = { "分裂魔法", "AzsharaのSpitelashにPolymorphをかけ、数秒後に現れる分身を殺して下さい。Polymorph Clone 50体を退治したら、AzsharaのArchmage Xylemのところへ戻って下さい。", "prismatic shellの独特な使い道が研究で分かったぞ。貝殻を持って行き、AzsharaにいるSpitelashどもにpolymorphの魔法を唱えるんだ。ほんのしばらく待てば、貝殻の混沌としたオーラの影響で、敵はいくつかの小さな分身に分かれる。その分身を素早く殺すと、貝殻は奴らの魂を集めるだろう。貝殻が満たされたら、戻ってきてくれ。", "魔力は集めたか?", "すごい! すごいぞ!これで変化の魔法を新しく作り変えられる。見てろ!", 0xd47cc0a5, 0x8be4d194, 0xbd600d96, 0xbb84400e, 0x4ee27b4c, "....." },
  [9365] = { "盗人の報酬", nil, nil, nil, "{name}、今日あなたは実力を示しました。\n\n差し上げられるものはあまりありませんが、覇者に相応しい冠ならあります。これがあなたの進む道を照らしますように。", 0x6fd2503e, nil, nil, nil, 0xe7fe3c18, ".mmm." },
  [9367] = { "Festival of Fire", "Stormwind、Ironforge、Darnassusのかがり火に触れ、首都にいるFestival Loremasterと話してください。", "今年もまたMidsummerがやって来た！\n\n毎年、しきたりに従って、我らの首都のかがり火の世話をする炎の守り手が選ばれるんだ。Azerothのいたるところで火が燃えているけれど、この季節にふさわしい敬意を払うためにも、我々の火こそが一番熱く、一番明るくなければならない。\n\n実は、もしよければ頼みたいことがあるんだ。すべての首都の火がちゃんと燃えているかどうか、まだ聞いていないんだよ。自分でそこへ行って、火にあたって温まってきてくれ――ちゃんと熱いか確かめるんだ！", "火は燃えているか?", "素晴らしい!あなたの言う通り篝火がよく手入れされているのなら、今年は忠実な炎の守り手たちを任命できたようですね。私の代わりに点検してくれてありがとう。さあ、私の敬意のささやかなしるしとして、これを受け取ってください。", 0x5796d45d, 0x043f46cc, 0x3508e9e2, 0xf5f9a813, 0x7dc83d5c, "....." },
  [9368] = { "Festival of Fire", "Orgrimmar、Thunder Bluff、Undercityのかがり火に触れ、首都にいるFestival Talespinnerと話してください。", "今年もまたMidsummerがやって来た！\n\n毎年、しきたりに従って、我らの首都のかがり火の世話をする炎の守り手が選ばれるんだ。Azerothのいたるところで火が燃えているけれど、この季節にふさわしい敬意を払うためにも、我々の火こそが一番熱く、一番明るくなければならない。\n\n実は、もしよければ頼みたいことがあるんだ。すべての首都の火がちゃんと燃えているかどうか、まだ聞いていないんだよ。自分でそこへ行って、火にあたって温まってきてくれ――ちゃんと熱いか確かめるんだ！", "うまくいったか、{name}?", "素晴らしい!あなたの言う通り篝火がよく手入れされているのなら、今年は忠実な炎の守り手たちを任命できたようですね。私の代わりに点検してくれてありがとう。さあ、私の敬意のささやかなしるしとして、これを受け取ってください。", 0x5796d45d, 0xcedbcab1, 0x3508e9e2, 0x10763147, 0x7dc83d5c, "....." },
  [9378] = { "DND FLAG 恐怖の城塞 - Naxxramas", "Eastern PlaguelandsのLight's Hope ChapelにいるArchmage Angela Dosantosが、Arcane Cloakingを無償で授けてくれる。Argent DawnからExaltedの評価を得ている必要がある。", "Plaguewoodの奥深くに、恐るべき城塞Naxxramasの入口がある。これまで、中に入ろうとする試みはすべて、ルーンのポータルにかけられた魔法の結界に阻まれてきた。そう、今まではな。\n\n我々は、いわば永続的な秘術の隠蔽によって中へ入る方法を考え出した――Kirin Torの古い簡易呪文に、私が少し手を加えたものだ。とはいえ、この隠蔽には金がかかる。だが、Dawnの大義に対するお前の献身は揺るぎない！費用はすべて免除しよう。", nil, nil, 0x5049ff9c, 0x69b682cf, 0x92dc890b, nil, nil, "...mm" },
  [9388] = { "Kalimdorに揺らめく炎", "Ashenvale、Barrens、Darkshore、Stonetalon Mountainsのかがり火を訪れ、Festival Flamekeeperと話してください。", "今日は世界中でたくさんの炎が燃えているんだ、{name}。一番世話が難しいのは緑に燃える火でね。見張っていないと長くは燃え続けないんだ。Kalimdorのエメラルド色の火が、我らの炎の守り手のためにまだ燃えているか確かめてきてくれるかい？\n\n火があるのは、BarrensのRatchetの近く、DarkshoreのMaster's Glaiveのそば、Ashenvaleの森のSilverwing Outpost近くの橋のたもと、そしてStonetalon Mountainsの大通り沿い、Windshear Cragへ向かう道の近くだ。", "祭りが終わるまで、火を絶やすわけにはいかん!", "ああ、まだ燃えているのですね。よかった。あの火が時を待たずに燃え尽きてしまうのは良くありませんから。よくやってくれました、{name}。私の祝福とともに、これを受け取ってください。", 0x4231b5a1, 0xebc13200, 0x9fb3b754, 0x7346e6f0, 0x87796b40, "....." },
  [9389] = { "Eastern Kingdomsに揺らめく炎", "Hillsbrad Foothills、Silverpine Forest、Westfall、Wetlandsのかがり火を訪れ、Festival Flamekeeperと話してください。", "Midsummer Fire Festivalは昔から、無数の炎でこの地を照らしてきた。緑の火こそ最高だと言う者もいる。保つのが一番難しく、それにあんなに独特な色合いをしているからね。\n\nEastern Kingdomsで、我らの炎の守り手のために緑の火がまだ燃えているか確かめてきてくれ。火があるのは、WetlandsのDun Modrの近く、Silverpine ForestのPyrewood Villageのそば、Westfallの灯台を見下ろす崖の上、そしてHillsbrad Foothillsの崩れた塔のそばだ。", "自分の務めは果たしたか?", "戻ってきたのですね。この大陸のエメラルドの炎を見届けてきたと。どう思いましたか、ん?確かに、珍しくて素晴らしい光景です。とはいえ、目に見える報酬のほうが喜ばれるのは承知しています……ですから、どうぞ、お手間をかけたお礼にこれを受け取ってください。", 0x97c31d69, 0x8c77ebbe, 0x389c2696, 0x6640bff5, 0xe62c73ec, "....." },
  [9415] = { "Marshal Bluewallへの報告", "Hive'Zora近くのAlliance野営地にいるMarshal Bluewallと話して下さい。", "あんたはMarshal Bluewallの新兵か? もちろんそうだよな。\n\n何を待ってるんだ? いい兵士は砂漠で死んでいく。そいつらに加わるなんてゾクゾクしないか?\n\nさあ、出発しろ。途中で干からびるなよ。", nil, "Allianceは戦うことのできる者すべてを必要としている。Hordeはこの大陸の北部から援軍供給を常に受けていて、我々はそれに追いつくのに苦心している。\n\nお前に現況を説明しよう。", 0x4008d111, 0x31d6c9a1, 0x8a5e1ea6, nil, 0x10702533, "...m." },
  [9416] = { "General Kirikaへの報告", "Hive'Regal近くにあるHorde野営地にいるGeneral Kirikaと話して下さい。", "お前はGeneral Kirikaの新兵の一人だな。ようやく来たか。砂漠では体がすぐに参っちまう。\n\nドワーフどもには毎日増援が来ている。Silithusの資源争いで、我々が陣地を失うわけにはいかない。\n\n指示は将軍から受けろ。お前を鍛えるのは俺の仕事じゃない。見つけるのが仕事だ。", nil, "お前がここにいてくれて良かった。だが、おしゃべりに費やしている時間はないのだ。お前には指示が必要だ。それから、出かけてもらわねばならん。\n\nよく聞け。", 0x99409d9a, 0x28dcdb78, 0xe9369a9b, nil, 0x55705a01, "...m." },
  [9419] = { "砂漠の掃除", "Silithystを発見し、Silithyst Extractorへ届けて下さい。その後、Hive'Zora近くのAlliance野営地にいるMarshal Bluewallと話して下さい。", "最近、我々はHordeが資源を見つけるためにSilithus砂漠をあさっていることに気が付いたが、あまり気に留めていなかった。この蒸し暑い砂漠へ多くの人員を配備するに値するものではないと考えたのだ。\n\nだがしかし、その資源の重要性が見出された今、我々は急ぎ拾い集めている。\n\nお前の助けを得られるならば、是非とも砂漠へ行きsilithystを発見して持ち帰ってもらいたい。", "向こうでは気をつけろ、だが急ぐのだ。無駄にできる時間はない。", "お前が成功したことを神に感謝する。\n\n今資源集めをより早く始めることができただけでも、我々の苦境はさほど絶望的なものにはならないだろう。我々は砂漠の恵みがHordeの手に落ちることのないよう、保ち続けねばならん。", 0xc1479db1, 0x04326ec8, 0xe009e48c, 0xf4c8a037, 0x7b5cf1a9, "....." },
  [9422] = { "砂漠の掃除", "Silithystを発見してSilithyst Extractorへ届け、Hive'Regal近くにあるHorde野営地のGeneral Kirikaと話して下さい。", "前から、我々はSilithus砂漠の水晶資源を採取している。直面した唯一の危険は、この場所を住処とする生物や、過酷な砂と埃と熱だった。\n\nしかし今、我々がここで発見した物の意味にAllianceが気づいてしまったらしい。今やそれは他者に資源を奪われないよう確保し、天然資源を争奪する競争となっているのだ。\n\n得られる助けすべてが必要だ。お前の助けも得られることを願っておる。", "砂漠の危険には用心しろ、{name}。Allianceが砂丘に潜んでいる今、一歩踏み出すごとにそれが最期になりかねん。", "よくやってくれた、{name}。この資源は備蓄品へ加えられるであろう。我らが得たあらゆる些細な物が、敵の損失となるのだ。", 0xc1479db1, 0xd0a8a42f, 0xa727e0fd, 0x62964905, 0x42cdb6c9, "....." },
  [9556] = { "勝者には……", "自陣営がEastern Plaguelandsで勝利しているときに、Stratholmeの街の中からStratholme Holy Waterをひと瓶集め、StormwindまたはUndercityのMage QuarterにいるLordaeron Mageに届けて下さい。", "塔の間で長く激しく戦ってきたのだろうな、{race}。この地を守ってくれたお返しに何かを贈りたいが、その前に、ここで起きた悲劇の重さを理解していることを我々に示してもらわねばならない。\n\nStratholmeの通りを歩き、holy waterの小瓶を見つけてくれ。手に入れたら、StormwindかUndercityのメイジ地区へ向かうのだ……そこで、この地で勝利を収めていれば、私の同僚に会えるだろう。", nil, nil, 0xe7d4c82f, 0x5e95b376, 0xeb8092b9, nil, nil, "...mm" },
  [9664] = { "新たな前哨基地の設営", "Eastern PlaguelandsのCrown Guard Tower、Eastwall Tower、Northpass Tower、Plaguewood Towerを占領し、Light's Hope ChapelのEmmisary Whitebeardのところへ戻って下さい。", "Plaguelandsへようこそ、{name}。知ってのとおり、我々の懸命な努力にもかかわらず、Forsakenとその同盟者たちはここより西の土地を押さえている。Allianceの司令官たちは、ここ東部に新たな防備を築き、敵を締め上げる輪を狭めることに決めた。\n\nLordaeronの時代から長く見捨てられてきた塔を、この目的のために奪い取り、建て直すのだ。この地は危険だ。君の助けがあれば心強い。", "塔を我々の支配下に置けば、ほどなくForsakenを包囲できるようになる。そうなれば、奴らを叩き潰すのは時間の問題だ。", "よくやった、{name}。今後の攻撃からこれらの塔を守り抜くことが重要だ。そのためには、この地域を確保する増援が到着するまで、君の助けが必要になるかもしれない。", 0x1b16d570, 0xd178e91f, 0x56bc8363, 0x18ee7a4a, 0x7ec604e7, "....." },
  [9665] = { "防衛の強化", "Eastern PlaguelandsのCrown Guard Tower、Eastwall Tower、Northpass Tower、Plaguewood Towerを占領し、Light's Hope ChapelのEmmisary Gormokのところへ戻って下さい。", "Forsakenの密偵が、ここEastern Plaguelandsの各地にある見捨てられた塔に新たな拠点を築こうというAllianceの企みを暴いた。\n\n奴らが我々の東の国境で大きな足場を築くのを許すわけにはいかん。だからこのAllianceの侵入を食い止めねばならんのだ。今の我々の計画は、奴らがすでに奪った塔からは奴らを追い出し、我々の手中にある塔は占拠してさらなる攻撃に備えることだ。", "我々の首都のすぐ近くに拠点を築くことを許すと思っているとは、奴らは愚か者に違いない。\n\n尻尾を巻いて南へ退却するまで、奴らの数を削り続けてやる。", "良い知らせだ、{name}。Allianceの軍勢を完全に押し返すまで、ここPlaguelandsでは絶え間ない戦いが続くだろう。\n\nその日が来るまで、引き続き君の助けを得られることを願っている。", 0x905ff178, 0x088acc5d, 0x65df63cb, 0x4ad0577c, 0x7fd2f5aa, "....." },
})
